import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const root='/home/runner/.local/share/omgithub-playwright';
const req=createRequire(join(root,'package.json'));
const {chromium}=req('playwright');
const cfg=JSON.parse(readFileSync(join(root,'linux.json'),'utf8'));
process.env.DISPLAY ||= ':'+readFileSync(join(root,'display'),'utf8').trim();
const browser=await chromium.launch(cfg.browser.launchOptions);
const page=await browser.newPage({viewport:{width:1000,height:700}});
const errors=[];
page.on('pageerror',e=>errors.push(e.message));
page.on('response',r=>{if(r.status()>=400)errors.push(`${r.status()} ${r.url()}`)});
const hold=async (...keys)=>{for(const k of keys) await page.keyboard.down(k); await page.waitForTimeout(1000); for(const k of keys) await page.keyboard.up(k)};
const snap=async label=>console.log(label,{loot:await page.locator('#loot').innerText(),cash:await page.locator('#cash').innerText(),clean:await page.locator('#clean').innerText(),toast:await page.locator('#toast').innerText()});
await page.goto('http://127.0.0.1:4173/',{waitUntil:'networkidle'});
await page.locator('#startBtn').click();
await page.keyboard.down('ArrowUp'); await page.waitForTimeout(1150); await page.keyboard.up('ArrowUp');
await page.keyboard.down('ArrowLeft'); await page.waitForTimeout(500); await page.keyboard.up('ArrowLeft');
await page.keyboard.press('e'); await snap('shop robbery');
await page.keyboard.down('Shift'); await page.keyboard.down('ArrowRight'); await page.keyboard.down('ArrowDown'); await page.waitForTimeout(2600); await page.keyboard.up('ArrowRight'); await page.keyboard.up('ArrowDown'); await page.keyboard.up('Shift');
await page.keyboard.press('e'); await page.waitForTimeout(100); await snap('seller interaction');
console.log('wanted',await page.locator('#wanted').evaluate(e=>e.classList.contains('active')),'errors',errors);
await browser.close();
EOF
